using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class ReportBendDependencies {public static string Main(){var road=GameObject.Find("Ground_CR133 mountain driving surface").GetComponent<MeshCollider>();var mf=GameObject.Find("Ground_ReportCleanup MountainLoop continuous solid 0").GetComponent<MeshFilter>();var mesh=UnityEngine.Object.Instantiate(mf.sharedMesh);var v=mesh.vertices;int changed=0;for(int i=0;i<v.Length;i++){var p=mf.transform.TransformPoint(v[i]);if(p.x<1320||p.x>1380||p.z<-300||p.z>-250)continue;if(road.Raycast(new Ray(p+Vector3.up*4,Vector3.down),out var h,8)&&p.y>h.point.y-.18f){p.y=h.point.y-.18f;v[i]=mf.transform.InverseTransformPoint(p);changed++;}}mesh.vertices=v;mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,"Assets/Track/ReportCleanup/forward-bend-seated-terrain.asset");mf.sharedMesh=mesh;mf.GetComponent<MeshCollider>().sharedMesh=mesh;Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(mf.gameObject.scene);EditorSceneManager.SaveScene(mf.gameObject.scene);AssetDatabase.SaveAssets();File.WriteAllText("Docs/ReportCleanup/BUG-015-dependencies.txt","Terrain vertices seated below the final local pavement grade: "+changed+". No buildings, fences or tree trunks occupy this pavement-only repair.");return "Seated "+changed+" terrain vertices";}}
